/* Generated by scripts/build.mjs from assets/postal.js — do not edit.
   Same statements, same order, same values; only the comments and the blank lines are
   gone. Edit assets/postal.js and rebuild. */
(function (root) {
  "use strict";

  const COUNTRY_CODES = (
    "AD AE AF AG AI AL AM AO AQ AR AS AT AU AW AX AZ BA BB BD BE BF BG BH BI BJ BL BM BN BO BQ BR BS BT BV BW BY BZ " +
    "CA CC CD CF CG CH CI CK CL CM CN CO CR CU CV CW CX CY CZ DE DJ DK DM DO DZ EC EE EG EH ER ES ET FI FJ FK FM FO FR " +
    "GA GB GD GE GF GG GH GI GL GM GN GP GQ GR GS GT GU GW GY HK HM HN HR HT HU ID IE IL IM IN IO IQ IR IS IT JE JM JO " +
    "JP KE KG KH KI KM KN KP KR KW KY KZ LA LB LC LI LK LR LS LT LU LV LY MA MC MD ME MF MG MH MK ML MM MN MO MP MQ MR " +
    "MS MT MU MV MW MX MY MZ NA NC NE NF NG NI NL NO NP NR NU NZ OM PA PE PF PG PH PK PL PM PN PR PS PT PW PY QA RE RO " +
    "RS RU RW SA SB SC SD SE SG SH SI SJ SK SL SM SN SO SR SS ST SV SX SY SZ TC TD TF TG TH TJ TK TL TM TN TO TR TT TV " +
    "TW TZ UA UG UM US UY UZ VA VC VE VG VI VN VU WF WS YE YT ZA ZM ZW"
  ).split(" ");

  const LANGUAGE_COUNTRY = {
    pl: "PL", uk: "UA", de: "DE", en: "GB", cs: "CZ", sk: "SK", ro: "RO",
    hr: "HR", sr: "RS", it: "IT", nl: "NL", es: "ES", fr: "FR",
  };

  const RULES = {
    PL: { pattern: /^\d{5}$/, format: (v) => `${v.slice(0, 2)}-${v.slice(2)}` },
    DE: { pattern: /^\d{5}$/ }, FR: { pattern: /^\d{5}$/ }, IT: { pattern: /^\d{5}$/ },
    ES: { pattern: /^\d{5}$/ }, HR: { pattern: /^\d{5}$/ }, RS: { pattern: /^\d{5}$/ },
    UA: { pattern: /^\d{5}$/ },
    AT: { pattern: /^\d{4}$/ }, CH: { pattern: /^\d{4}$/ }, BE: { pattern: /^\d{4}$/ },
    LU: { pattern: /^\d{4}$/ },
    CZ: { pattern: /^\d{5}$/, format: (v) => `${v.slice(0, 3)} ${v.slice(3)}` },
    SK: { pattern: /^\d{5}$/, format: (v) => `${v.slice(0, 3)} ${v.slice(3)}` },
    RO: { pattern: /^\d{6}$/ },
    NL: { pattern: /^\d{4}[A-Z]{2}$/, format: (v) => `${v.slice(0, 4)} ${v.slice(4)}` },
  };

  const fileCache = new Map();

  function normalize(value) {
    return String(value == null ? "" : value).toUpperCase().replace(/[\s-]/g, "");
  }

  function validate(country, value) {
    const raw = String(value == null ? "" : value).trim();
    if (!raw) return true;
    const rule = RULES[String(country || "").toUpperCase()];
    return rule ? rule.pattern.test(normalize(raw)) : raw.length <= 12;
  }

  function format(country, value) {
    const raw = String(value == null ? "" : value).trim();
    const key = normalize(raw);
    const rule = RULES[String(country || "").toUpperCase()];
    if (!rule || !rule.pattern.test(key)) return raw;
    return rule.format ? rule.format(key) : key;
  }

  function countryName(code, lang) {
    try {
      return new Intl.DisplayNames([lang || "pl"], { type: "region" }).of(code) || code;
    } catch (error) {
      return code;
    }
  }

  function defaultCountry(lang) {
    return LANGUAGE_COUNTRY[String(lang || "").toLowerCase()] || "PL";
  }

  function lookupKey(country, value) {
    const key = normalize(value);
    return String(country || "").toUpperCase() === "NL" ? key.slice(0, 4) : key;
  }

  async function places(country, value) {
    const code = String(country || "").toLowerCase();
    const key = lookupKey(country, value);
    if (!validate(country, value) || !key || !RULES[code.toUpperCase()]) return [];
    const path = `/assets/postal/${code}/${key.slice(0, 2).toLowerCase()}.json`;
    if (!fileCache.has(path)) {

      fileCache.set(path, fetch(path).then((response) => response.ok ? response.json() : {})
        .catch(() => { fileCache.delete(path); return {}; }));
    }
    const data = await fileCache.get(path);
    return Array.isArray(data[key]) ? data[key].slice() : [];
  }

  function fillCountries(select, lang) {
    const current = select.value;
    const rows = COUNTRY_CODES.map((code) => ({ code, name: countryName(code, lang) }))
      .sort((a, b) => a.name.localeCompare(b.name, lang));
    select.innerHTML = rows.map((row) => `<option value="${row.code}">${row.name}</option>`).join("");
    if (current && COUNTRY_CODES.includes(current)) select.value = current;
  }

  function bind(options) {
    const country = options.country;
    const postal = options.postal;
    const city = options.city;
    const error = options.error;
    const datalist = options.datalist;
    const lang = options.lang || document.documentElement.lang || "pl";
    fillCountries(country, lang);
    country.value = options.defaultCountry || defaultCountry(lang);

    let request = 0;
    const showError = (show) => {
      postal.setAttribute("aria-invalid", String(show));
      error.hidden = !show;
    };
    const update = async (showInvalid) => {
      const valid = validate(country.value, postal.value);
      if (valid && postal.value) postal.value = format(country.value, postal.value);
      showError(Boolean(showInvalid && !valid));
      datalist.replaceChildren();
      if (!valid || !postal.value) return valid;
      const ownRequest = ++request;
      const matches = await places(country.value, postal.value);
      if (ownRequest !== request) return valid;
      matches.forEach((name) => {
        const option = document.createElement("option");
        option.value = name;
        datalist.appendChild(option);
      });

      const autoFilled = city.dataset.autoCity && city.value === city.dataset.autoCity;
      if (matches.length === 1 && (!city.value || autoFilled || !matches.includes(city.value))) {
        city.value = matches[0];
        city.dataset.autoCity = matches[0];
      } else if (autoFilled && !matches.includes(city.value)) {
        city.value = "";
      }
      return valid;
    };

    country.addEventListener("change", () => {
      postal.value = format(country.value, postal.value);
      update(Boolean(postal.value));
    });
    postal.addEventListener("input", () => update(false));
    postal.addEventListener("blur", () => update(true));
    return {
      validate: () => {
        const valid = validate(country.value, postal.value);
        if (valid) postal.value = format(country.value, postal.value);
        showError(!valid);
        if (!valid) postal.focus();
        return valid;
      },
      setCountry: (value) => { country.value = value || options.defaultCountry || defaultCountry(lang); },
      refresh: update,
    };
  }

  root.LMPostal = { COUNTRY_CODES, RULES, normalize, validate, format, countryName, defaultCountry, places, bind };
}(typeof window === "undefined" ? globalThis : window));
